// Keeps the embedded copies and generated files in contracts/ equal to their source schemas.
// The validator only follows $ref inside one file, so these files carry a copy:
//   profile.schema.json -> $defs.profile in api/error, api/me_profile_get.response, api/me_profile_put.request
//   extract.schema.json -> $defs.extract in api/ai_read.response
//   events.schema.json  -> api/event/<type>.request.schema.json, one strict request schema per event type (deviations D6),
//                          and event_schemas.js, the same schemas as a plain module for the server and the browser
// Run: node contracts/sync.mjs          (rewrite the copies and generated files)
//      node contracts/sync.mjs --check  (exit 1 if any differs; the tests do the same check)
import fs from 'node:fs'; import path from 'node:path'; import { fileURLToPath } from 'node:url';

export const DIR = path.dirname(fileURLToPath(import.meta.url));
const read = f => JSON.parse(fs.readFileSync(path.join(DIR, f), 'utf8'));
const META = ['$schema', '$id', 'title'];
export const body = s => { const o = { ...s }; for (const k of META) delete o[k]; return o; };

// [api file, where the copy lives ('$defs.<name>'), source file]
export const COPIES = [
  ['api/error.schema.json', '$defs.profile', 'profile.schema.json'],
  ['api/me_profile_get.response.schema.json', '$defs.profile', 'profile.schema.json'],
  ['api/me_profile_put.request.schema.json', '$defs.profile', 'profile.schema.json'],
  ['api/ai_read.response.schema.json', '$defs.extract', 'extract.schema.json'],
];
export const EVENT_DIR = 'api/event';
export const EVENT_MODULE = 'event_schemas.js';

// The strict POST /api/v1/event request schema for one type, built from events.schema.json.
export function eventRequestSchema(events, type) {
  return {
    $schema: events.$schema,
    $id: `contracts/${EVENT_DIR}/${type}.request.schema.json`,
    title: `event ${type} request`,
    description: `POST /api/v1/event with type "${type}" (SPEC 9, ADR-08, deviations D6). Strict: type must be "${type}" and data allows only the ${type} fields, so a body that mixes fields of two types fails. The handler picks this schema by the body's type with schemaForType(type) from contracts/event_schemas.js; an unknown type is bad_request. Generated from events.schema.json by contracts/sync.mjs: do not edit by hand.`,
    type: 'object',
    additionalProperties: false,
    required: ['type', 'eid', 'data'],
    properties: {
      type: { type: 'string', enum: [type] },
      eid: events.properties.eid,
      data: events.$defs[type],
    },
  };
}

function eventModule(schemas) {
  return `// GENERATED by contracts/sync.mjs from events.schema.json. Do not edit by hand: change events.schema.json, then run node contracts/sync.mjs.
// The POST /api/v1/event request schemas, one per event type (BACKEND ADR-08, deviations D6). The same schemas are in
// contracts/api/event/<type>.request.schema.json for other readers. A plain module with no imports of JSON or Node, so the
// server bundle and the browser can load it. The validator has no oneOf, so the handler selects the schema by the body's type:
//   const schema = schemaForType(body && body.type);   // null for an unknown type: answer bad_request
//   const r = validate(schema, body);                  // one step: envelope and data together
// checkEvent(body) does both and returns {ok, errors} like validate().
import { validate } from './validate_lib.js';

const freeze = v => { if (v && typeof v === 'object') { for (const x of Object.values(v)) freeze(x); Object.freeze(v); } return v; };
const SCHEMAS = freeze(${format(schemas)});

export const EVENT_TYPES = Object.freeze(Object.keys(SCHEMAS));
// The strict request schema for one event type, or null when the type is not a known event type (never a prototype key).
export function schemaForType(type) {
  return typeof type === 'string' && Object.prototype.hasOwnProperty.call(SCHEMAS, type) ? SCHEMAS[type] : null;
}
export function checkEvent(body) {
  const schema = schemaForType(body && typeof body === 'object' && !Array.isArray(body) ? body.type : undefined);
  if (!schema) return { ok: false, errors: [{ path: '$.type', message: 'is not a known event type' }] };
  return validate(schema, body);
}
`;
}

// Returns [{file, at, source, same, text}] without writing anything. text is the wanted file content, or null to delete the file.
export function plan() {
  const out = [];
  for (const [file, at, source] of COPIES) {
    const doc = read(file), want = body(read(source)), name = at.split('.')[1];
    const same = JSON.stringify(sorted(doc.$defs[name])) === JSON.stringify(sorted(want));
    out.push({ file, at, source, same, text: format({ ...doc, $defs: { ...doc.$defs, [name]: want } }) + '\n' });
  }
  const events = read('events.schema.json'), types = Object.keys(events.$defs), schemas = {};
  for (const t of types) {
    const file = `${EVENT_DIR}/${t}.request.schema.json`, want = eventRequestSchema(events, t); schemas[t] = want;
    const p = path.join(DIR, file), have = fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, 'utf8')) : null;
    out.push({ file, at: '*', source: `events.schema.json $defs.${t}`, same: JSON.stringify(sorted(have)) === JSON.stringify(sorted(want)), text: format(want) + '\n' });
  }
  const dir = path.join(DIR, EVENT_DIR);
  for (const f of fs.existsSync(dir) ? fs.readdirSync(dir).sort() : []) {
    const t = f.replace(/\.request\.schema\.json$/, '');
    if (!types.includes(t)) out.push({ file: `${EVENT_DIR}/${f}`, at: '*', source: 'events.schema.json (no such type)', same: false, text: null });
  }
  const js = eventModule(schemas), mp = path.join(DIR, EVENT_MODULE);
  out.push({ file: EVENT_MODULE, at: '*', source: 'events.schema.json', same: fs.existsSync(mp) && fs.readFileSync(mp, 'utf8') === js, text: js });
  return out;
}
// JSON with 2-space indent, but lists of plain values on one line, so enums stay readable.
export function format(v, ind = '') {
  const next = ind + '  ';
  if (Array.isArray(v)) {
    if (!v.length) return '[]';
    if (v.every(x => x === null || typeof x !== 'object')) return '[' + v.map(x => JSON.stringify(x)).join(', ') + ']';
    return '[\n' + v.map(x => next + format(x, next)).join(',\n') + '\n' + ind + ']';
  }
  if (v && typeof v === 'object') {
    const ks = Object.keys(v); if (!ks.length) return '{}';
    return '{\n' + ks.map(k => next + JSON.stringify(k) + ': ' + format(v[k], next)).join(',\n') + '\n' + ind + '}';
  }
  return JSON.stringify(v);
}
const sorted = v => Array.isArray(v) ? v.map(sorted) : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map(k => [k, sorted(v[k])])) : v;

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const check = process.argv.includes('--check'); let bad = 0;
  for (const p of plan()) {
    if (p.same) continue;
    bad++;
    if (check) { console.error(`${p.file}: ${p.at} differs from ${p.source}`); continue; }
    const f = path.join(DIR, p.file);
    if (p.text === null) { fs.unlinkSync(f); console.log(`removed ${p.file}`); continue; }
    fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, p.text);
    console.log(`updated ${p.file}`);
  }
  if (check && bad) process.exit(1);
  if (!bad) console.log('all copies match');
}
